-- 018_reimport_bean.sql
-- Re-import ถั่ว: import รอบแรกอ่านผิด (layout ถั่วมี 2 ทางเลือกไรโซเบียม + สูตร 0-46-0)
--   เดิม: มีแค่ OM<1, grade เป็นข้อความ, เหลือเลขเดียว
--   ใหม่: 12 combo (OM<1 & >1) × 2 ทางเลือก, สูตรจริง (46-0-0/0-46-0/0-0-60)
-- ที่มา: ไฟล์ '4. ถั่ว-...ใหม่.xlsx' ชีต 'ถั่ว-แม่ปุ๋ย' (ตรงกับไฟล์ 6)
-- ช่วงค่าดิน [min,max) ตามแบบพืชไร่อื่น; '-' ในตาราง = ไม่ใส่ปุ๋ยตัวนั้น (ข้าม)

delete from public.crop_fertilizer_plan where crop_id = '36dfa848-92fc-400f-84c0-5e49618c19c4';


-- แก้ step 4 (fertilizer_recommendations) ให้ตรงไฟล์ 6:
--   N ที่ OM<1 : 0 -> 3   |   K2O ที่ K>40 : 3 -> 0
update public.fertilizer_recommendations set target_n = 3, updated_at = now()
where crop_id = '36dfa848-92fc-400f-84c0-5e49618c19c4' and mode = '100%' and om_min = 0 and p_min is null and k_min is null;

update public.fertilizer_recommendations set target_k2o = 0, updated_at = now()
where crop_id = '36dfa848-92fc-400f-84c0-5e49618c19c4' and mode = '100%' and k_min = 40.001 and om_min is null and p_min is null;